def ks_statistic(a, b):
    """Return the two-sample Kolmogorov-Smirnov statistic."""
    xs, ys = sorted(a), sorted(b)
    return max(abs(x - y) for x, y in zip(xs, ys))

tests_py:
def test_identical():
    assert solution.ks_statistic([1, 2, 3], [1, 2, 3]) == 0.0

def test_separated():
    assert solution.ks_statistic([1, 2], [3, 4]) == 1.0

def test_unequal_lengths():
    assert abs(solution.ks_statistic([1, 2, 3, 4], [2, 3]) - 0.25) < 1e-12

def test_shifted():
    d = solution.ks_statistic(list(range(10)), list(range(5, 15)))
    assert abs(d - 0.5) < 1e-12

def test_balanced_spread():
    # equal means, different shapes: a mean-only test would miss this
    assert abs(solution.ks_statistic([1, 2, 3, 4], [1, 1, 4, 4]) - 0.25) < 1e-12

def test_empty():
    for a, b in (([], [1]), ([1], [])):
        try:
            solution.ks_statistic(a, b)
        except ValueError:
            continue
        raise AssertionError("expected ValueError")

def test_symmetry():
    a, b = [1, 3, 4, 7], [2, 3, 5]
    assert solution.ks_statistic(a, b) == solution.ks_statistic(b, a)
